declare
  d constant jsonb := $content${"units":[{"id":"a1-u13","language_code":"en","level":"A1","position":13,"title_es":"Letras y datos personales","title_en":"Letters and personal details","description_es":"El alfabeto, deletrear y dar datos personales en un formulario.","emoji":"🔤","objective_es":"Podés deletrear un nombre y entender un formulario con datos personales.","grammar":null,"review_status":"draft"},{"id":"a1-u14","language_code":"en","level":"A1","position":14,"title_es":"Precios y compras","title_en":"Prices and shopping","description_es":"Los números hasta el 100, los precios y cómo pedir en una tienda.","emoji":"🛍️","objective_es":"Podés entender precios y lo que se pide en una tienda.","grammar":null,"review_status":"draft"}],"words":[{"id":"en-alphabet","language_code":"en","unit_id":"a1-u13","text":"alphabet","translation_es":"alfabeto","accepted_translations":["abecedario"],"ipa":"/ˈælfəˌbɛt/","romanization":null,"emoji":"🔤","example_en":"A, B, C: the alphabet.","example_es":"A, B, C: el alfabeto.","difficulty":1,"tags":["alphabet"]},{"id":"en-letter","language_code":"en","unit_id":"a1-u13","text":"letter","translation_es":"letra","accepted_translations":[],"ipa":"/ˈlɛtər/","romanization":null,"emoji":"🅰️","example_en":"A is a letter.","example_es":"La A es una letra.","difficulty":1,"tags":["alphabet"]},{"id":"en-spell","language_code":"en","unit_id":"a1-u13","text":"spell","translation_es":"deletrear","accepted_translations":[],"ipa":"/spɛl/","romanization":null,"emoji":null,"example_en":"Please spell your name.","example_es":"Por favor, deletreá tu nombre.","difficulty":1,"tags":["alphabet","verbs"]},{"id":"en-how-do-you-spell-it","language_code":"en","unit_id":"a1-u13","text":"how do you spell it","translation_es":"¿cómo se escribe?","accepted_translations":["¿cómo se deletrea?"],"ipa":"/haʊ du ju ˈspɛl ɪt/","romanization":null,"emoji":null,"example_en":"Garcia? How do you spell it?","example_es":"¿García? ¿Cómo se escribe?","difficulty":1,"tags":