:"Thirty students.","example_es":"Treinta estudiantes.","difficulty":1,"tags":["numbers"]},{"id":"en-forty","language_code":"en","unit_id":"a1-u14","text":"forty","translation_es":"cuarenta","accepted_translations":[],"ipa":"/ˈfɔrti/","romanization":null,"emoji":null,"example_en":"My father is forty.","example_es":"Mi papá tiene cuarenta años.","difficulty":1,"tags":["numbers"]},{"id":"en-fifty","language_code":"en","unit_id":"a1-u14","text":"fifty","translation_es":"cincuenta","accepted_translations":[],"ipa":"/ˈfɪfti/","romanization":null,"emoji":null,"example_en":"Fifty books.","example_es":"Cincuenta libros.","difficulty":1,"tags":["numbers"]},{"id":"en-sixty","language_code":"en","unit_id":"a1-u14","text":"sixty","translation_es":"sesenta","accepted_translations":[],"ipa":"/ˈsɪksti/","romanization":null,"emoji":null,"example_en":"My grandfather is sixty.","example_es":"Mi abuelo tiene sesenta años.","difficulty":1,"tags":["numbers"]},{"id":"en-seventy","language_code":"en","unit_id":"a1-u14","text":"seventy","translation_es":"setenta","accepted_translations":[],"ipa":"/ˈsɛvənti/","romanization":null,"emoji":null,"example_en":"Seventy cups.","example_es":"Setenta tazas.","difficulty":1,"tags":["numbers"]},{"id":"en-eighty","language_code":"en","unit_id":"a1-u14","text":"eighty","translation_es":"ochenta","accepted_translations":[],"ipa":"/ˈeɪti/","romanization":null,"emoji":null,"example_en":"My grandmother is eighty.","example_es":"Mi abuela tiene ochenta años.","difficulty":1,"tags":["numbers"]},{"id":"en-ninety","language_code":"en","unit_id":"a1-u14","text":"ninety","translation_es":"noventa","accepted_translations":[],"ipa":"/ˈnaɪnti/","romanization":null,"emoji":null,"example_en":"The computer is ninety dollars.","example_es":"La computadora cuesta noventa dólares.","difficulty":1,"tags":["numbers"]},{"id":"en-one-hundred","language_code":"en","unit_id":"a1-u14","text":"one hundred","translation_es":"cien","accepted_translations":["ciento"],"ipa":"/wʌn ˈhʌndrəd/","romanization":null,"emoji":"💯","example_en":"One hundred dollars.","example_es":"Cien dólares.","difficulty":1,"tags":["numbers"]},{"id":"en-dollar","language_code":"en","unit_id":"a1-u14","text":"dollar","translation_es":"dólar","accepted_translations":[],"ipa":"/ˈdɑlər/","romanization":null,"emoji":"💵","example_en":"The book is ten dollars.","example_es":"El libro cuesta diez dólares.","difficulty":1,"tags":["money"]},{"id":"en-cent","language_code":"en","unit_id":"a1-u14","text":"cent","translation_es":"centavo","accepted_translations":[],"ipa":"/sɛnt/","romanization":null,"emoji":"🪙","example_en":"Fifty cents.","example_es":"Cincuenta centavos.","difficulty":1,"tags":["money"]},{"id":"en-a-cup-of","language_code":"en","unit_id":"a1-u14","text":"a cup of","translation_es":"una taza de","accepted_translations":[],"ipa":"/ə ˈkʌp əv/","romanization":null,"emoji":"☕","example_en":"A cup of tea, please.","example_es":"Una taza de té, por favor.","difficulty":1,"tags":["quantities"]},{"id":"en-a-glass-of","language_code":"en","unit_id":"a1-u14","text":"a glass of","translation_es":"un vaso de","accepted_translations":[],"ipa":"/ə ˈɡlæs əv/","romanization":null,"emoji":"🥛","example_en":"A glass of water, please.","example_es":"Un vaso de agua, por favor.","difficulty":1,"tags":["quantities"]},{"id":"en-a-bottle-of","language_code":"en","unit_id":"a1-u14","text":"a bottle of","translation_es":"una botella de","accepted_translations":[],"ipa":"/ə ˈbɑtəl əv/","romanization":null,"emoji":"🍾","example_en":"A bottle of milk.","example_es":"Una botella de leche.","difficulty":1,"tags":["quantities"]},{"id":"en-a-kilo-of","language_code":"en","unit_id":"a1-u14","text":"a kilo of","translation_es":"un kilo de","accepted_translations":[],"ipa":"/ə ˈkiloʊ əv/","romanization":null,"emoji":"⚖️","example_en":"A kilo of rice.","example_es":"Un kilo de arroz.","difficulty":1,"tags":["quantities"]},{"id":"en-id-like","language_code":"en","unit_id":"a1-u14","text":"I'd like","translation_es":"quisiera","accepted_translations":[],"ipa":"/aɪd ˈlaɪk/","romanization":null,"emoji":null,"example_en":"I'd like a coffee, please.","example_es":"Quisiera un café, por favor.","difficulty":1,"tags":["shopping","requests"]},{"id":"en-anything-else","language_code":"en","unit_id":"a1-u14","text":"anything else","translation_es":"¿algo más?","accepted_translations":[],"ipa":"/ˈɛniˌθɪŋ ˈɛls/","romanization":null,"emoji":null,"example_en":"Anything else?","example_es":"¿Algo más?","difficulty":1,"tags":["shopping"]},{"id":"en-thats-all","language_code":"en","unit_id":"a1-u14","text":"that's all","translation_es":"eso es todo","accepted_translations":["nada más"],"ipa":"/ðæts ˈɔl/","romanization":null,"emoji":null,"example_en":"No, that's all, thank you.","example_es":"No, eso es todo, gracias.","difficulty":1,"tags":["shopping"]},{"id":"en-here-you-are","language_code":"en","unit_id":"a1-u14","text":"here you are","translation_es":"aquí tiene","accepted_translations":["aquí tenés","tome"],"ipa":"/ˈhɪr ju ˌɑr/","romanization":null,"emoji":null,"example_en":"Here you are. Ten dollars.","example_es":"Aquí tiene. Diez dólares.","difficulty":1,"tags":["shopping"]}],"lessons":[{"id":"a1-u13-l01","unit_id":"a1-u13","position":1,"title_es":"El alfabeto","objective_es":"Reconocer las letras del alfabeto inglés por su nombre.","intro":{"explanation":"Las letras se escriben igual que en español, pero sus nombres suenan distinto: la A se dice «éi», la E «i» y la I «ái». Las que más se confunden son la E y la I, y la G («yi») y la J («yéi»).","examples":[{"target":"A, E, I.","base":"A, E, I (se dicen «éi», «i», «ái»)."},{"target":"My name is Ana: A-N-A.","base":"Me llamo Ana: A-N-A."}]},"takeaways":["Reconocés las letras del alfabeto inglés por su nombre.","Distinguís de oído la E de la I y la G de la J."]},{"id":"a1-u13-l02","unit_id":"a1-u13","position":2,"title_es":"Deletrear","objective_es":"Pedir que alguien deletree y entender un nombre deletreado.","intro":{"explanation":"Para pedir que te deletreen una palabra se pregunta How do you spell it? (¿cómo se escribe?). Se responde letra por letra, y dos letras iguales seguidas se dicen con double: Ross es R-O-double S.","examples":[{"target":"How do you spell it?","base":"¿Cómo se escribe?"},{"target":"Ross: R-O-double S.","base":"Ross: R-O-doble S."}]},"takeaways":["Preguntás cómo se escribe algo con How do you spell it?","Deletreás un nombre y usás double para las letras repetidas."]},{"id":"a1-u13-rev1","unit_id":"a1-u13","position":3,"title_es":"Repaso 1","objective_es":"Consolidar «El alfabeto» y «Deletrear».","intro":null,"takeaways":[]},{"id":"a1-u13-l03","unit_id":"a1-u13","position":4,"title_es":"Nacionalidades","objective_es":"Decir la nacionalidad y preguntar la de otra persona.","intro":{"explanation":"El país es Mexico; la nacionalidad, Mexican. En inglés las nacionalidades van siempre con mayúscula: I am Argentinian. Spanish y English son también los nombres de los idiomas. Para preguntarla: What is your nationality?","examples":[{"target":"I am Mexican.","base":"Soy mexicano."},{"target":"She is from Spain. She is Spanish.","base":"Es de España. Es española."},{"target":"What is your nationality?","base":"¿Cuál es tu nacionalidad?"}]},"takeaways":["Decís la nacionalidad con to be y mayúscula: I am Argentinian.","Preguntás la nacionalidad con What is your nationality?"]},{"id":"a1-u13-l04","unit_id":"a1-u13","position":5,"title_es":"Teléfono, email y dirección","objective_es":"Entender y pedir un número de teléfono, un correo y una dirección.","intro":{"explanation":"Para pedir un dato se usa What is your…?: What is your phone number? What is your email? What is your address? Los números de teléfono se dicen cifra por cifra. Los datos de esta lección son de Sofia Ruiz, una persona inventada.","examples":[{"target":"What is your phone number?","base":"¿Cuál es tu número de teléfono?"},{"target":"What is your email?","base":"¿Cuál es tu correo electrónico?"}]},"takeaways":["Pedís un teléfono, un correo o una dirección con What is your…?","Reconocés un número de teléfono y un correo en un texto."]},{"id":"a1-u13-rev2","unit_id":"a1-u13","position":6,"title_es":"Repaso 2","objective_es":"Consolidar «Nacionalidades» y «Teléfono, email y dirección».","intro":null,"takeaways":[]},{"id":"a1-u13-l05","unit_id":"a1-u13","position":7,"title_es":"Completar un formulario","objective_es":"Completar y leer un formulario con datos personales.","intro":{"explanation":"Un formulario (form) pide los datos campo por campo: First name es el nombre de pila; Surname, el apellido; Age, la edad, y City, la ciudad. Se completa con el dato solo, sin oración: Surname: Ruiz. Practicás con el formulario de Sofia Ruiz, una persona inventada.","examples":[{"target":"First name: Sofia. Surname: Ruiz.","base":"Nombre: Sofia. Apellido: Ruiz."},{"target":"What is your surname?","base":"¿Cuál es tu apellido?"}]},"takeaways":["Entendés los campos de un formulario: first name, surname, age, city.","Sacás de un formulario el dato que te piden."]},{"id":"a1-u13-listen","unit_id":"a1-u13","position":8,"title_es":"Práctica de escucha","objective_es":"Reconocer de oído las palabras y frases de la unidad.","intro":null,"takeaways":[]},{"id":"a1-u13-words","unit_id":"a1-u13","position":9,"title_es":"Palabras de la unidad","objective_es":"Fijar el vocabulario de la unidad: reconocerlo y escribirlo.","intro":null,"takeaways":[]},{"id":"a1-u13-final","unit_id":"a1-u13","position":10,"title_es":"Repaso final","objective_es":"Demostrar todo lo de «Letras y datos personales».","intro":null,"takeaways":[]},{"id":"a1-u14-l01","unit_id":"a1-u14","position":1,"title_es":"Del 21 al 100","objective_es":"Contar de diez en diez hasta cien y armar los números del 21 al 99.","intro":{"explanation":"Las decenas terminan en -ty: thirty (30), forty (40), fifty (50). Forty se escribe sin u, aunque four la lleva. Del 21 al 99 se unen con guion: twenty-one, thirty-five. El 100 es one hundred.","examples":[{"target":"Thirty-five students.","base":"Treinta y cinco estudiantes."},{"target":"My grandmother is ninety.","base":"Mi abuela tiene noventa años."}]},"takeaways":["Contás de diez en diez hasta one hundred.","Armás los números del 21 al 99 con guion: forty-two."]},{"id":"a1-u14-l02","unit_id":"a1-u14","position":2,"title_es":"Precios y dinero","objective_es":"Decir y entender precios en dólares y centavos.","intro":{"explanation":"El símbolo va antes del número ($5), pero se dice después: five dollars. Un dólar tiene cien centavos (cents). Para decir un precio alcanza con to be: The book is twenty dollars. Algo barato es cheap y algo caro, expensive.","examples":[{"target":"The book is twenty dollars.","base":"El libro cuesta veinte dólares."},{"target":"A big bag, ten dollars? It is cheap!","base":"¿Una bolsa grande a diez dólares? ¡Es barata!"}]},"takeaways":["Decís un precio con to be: The coffee is three dollars.","Entendés de oído precios con dólares y centavos."]},{"id":"a1-u14-rev1","unit_id":"a1-u14","position":3,"title_es":"Repaso 1","objective_es":"Consolidar «Del 21 al 100» y «Precios y dinero».","intro":null,"takeaways":[]},{"id":"a1-u14-l03","unit_id":"a1-u14","position":4,"title_es":"How much, how many","objective_es":"Preguntar precios y cantidades con how much y how many.","intro":{"explanation":"How much pregunta un precio: How much is the bag? How many va con cosas que se cuentan, en plural: How many apples are there? Se responde con el número: There are three apples. / It is ten dollars.","examples":[{"target":"How much is the bag?","base":"¿Cuánto cuesta la bolsa?"},{"target":"How many cups are there?","base":"¿Cuántas tazas hay?"}]},"takeaways":["Preguntás un precio con How much is…?","Preguntás una cantidad con How many + plural."]},{"id":"a1-u14-l04","unit_id":"a1-u14","position":5,"title_es":"Una taza de, una botella de","objective_es":"Pedir cantidades de comida y bebida con I’d like.","intro":{"explanation":"Para pedir una cantidad: a cup of + bebida (a cup of tea), a glass of (water), a bottle of (milk), a kilo of (apples). Para pedir con cortesía se usa I'd like (quisiera): es más amable que I want.","examples":[{"target":"I'd like a cup of tea, please.","base":"Quisiera una taza de té, por favor."},{"target":"Two bottles of water.","base":"Dos botellas de agua."}]},"takeaways":["Pedís cantidades con a cup of, a glass of, a bottle of y a kilo of.","Pedís con cortesía con I'd like."]},{"id":"a1-u14-rev2","unit_id":"a1-u14","position":6,"title_es":"Repaso 2","objective_es":"Consolidar «How much, how many» y «Una taza de, una botella de».","intro":null,"takeaways":[]},{"id":"a1-u14-l05","unit_id":"a1-u14","position":7,"title_es":"En la tienda","objective_es":"Pedir, preguntar el precio y pagar en una tienda.","intro":{"explanation":"En una tienda se pide con I'd like y se pregunta el precio con How much is it? El vendedor pregunta Anything else? (¿algo más?). Si no querés nada más: No, that's all, thank you. Al pagar o entregar algo se dice Here you are (aquí tiene).","examples":[{"target":"Anything else?","base":"¿Algo más?"},{"target":"No, that's all. Here you are.","base":"No, eso es todo. Aquí tiene."}]},"takeaways":["Hacés un pedido completo: I'd like…, How much is it?, That's all.","Entendés lo que pregunta el vendedor y respondés con Here you are al pagar."]},{"id":"a1-u14-listen","unit_id":"a1-u14","position":8,"title_es":"Práctica de escucha","objective_es":"Reconocer de oído las palabras y frases de la unidad.","intro":null,"takeaways":[]},{"id":"a1-u14-words","unit_id":"a1-u14","position":9,"title_es":"Palabras de la unidad","objective_es":"Fijar el vocabulario de la unidad: reconocerlo y escribirlo.","intro":null,"takeaways":[]},{"id":"a1-u14-final","unit_id":"a1-u14","position":10,"title_es":"Repaso final","objective_es":"Demostrar todo lo de «Precios y compras».","intro":null,"takeaways":[]}],"exercises":[{"id":"a1-u13-l01-e01","lesson_id":"a1-u13-l01","position":1,"type"