6279c12eab474ed49d2127e2bf86737a46e59a97e51364c30b483fedbed7"},{"exercise_id":"a1-u14-rev2-e05","item_id":"en.gen.listen_choice.en-a-kilo-of","options_hash":"v1:5fc1b5958cb3504f0c4910c49fb68990b0bf4b709b3ef61a40eb4458e21aed19"},{"exercise_id":"a1-u14-rev2-e07","item_id":"en.ex.m0sc65firj9ck8","options_hash":"v1:c7627f6048f5ad922b27821a1e6bd5e0c6201140ba300b8d2a2e7d7c7a3048ca"},{"exercise_id":"a1-u14-rev2-e10","item_id":"en.ex.3p2ebx3ufa5rod","options_hash":"v1:1ffb819bfc5d7968f99b96072f50513ba1f4d67ca99a317a990de765e9c405d8"},{"exercise_id":"a1-u14-l05-e01","item_id":"en.ex.ym3areexofk37x","options_hash":"v1:8ae7f98624540128c292c344c2976cd0c2585e8265315899fdba3d75ed46f7a7"},{"exercise_id":"a1-u14-l05-e02","item_id":"en.ex.izpx2feefa2qac","options_hash":"v1:7d8d2df084d9d75c7dd960d8b6b70796bb5001aed110927cb4b2928e7bdcaf4a"},{"exercise_id":"a1-u14-l05-e03","item_id":"en.ex.xwzgoyltxi6uee","options_hash":"v1:eaf8b1f236b987de1aca7fc9b19b37c14292f93ee91b359775532d472fe8ce7e"},{"exercise_id":"a1-u14-l05-e04","item_id":"en.ex.8r4b4yxtex1icf","options_hash":"v1:b777be3e219b6166eea7ff9680f0870ca03cda4fa47b359be3acee93af654ae2"},{"exercise_id":"a1-u14-l05-e05","item_id":"en.ex.1fknub46980ygn","options_hash":"v1:f093a0a2d9d0827f4376d190b145afe3a156cbdfb045c42424a3be0b72ee6c40"},{"exercise_id":"a1-u14-listen-e01","item_id":"en.gen.listen_choice.en-one-hundred","options_hash":"v1:6dd91f1d1042cc910978e2b06260272397df6ea2e26b0e698cb8eed69eddbe65"},{"exercise_id":"a1-u14-listen-e02","item_id":"en.ex.kkpl2sqfk9eaxx","options_hash":"v1:adb4af7c537cf43883017d07f4aa3e98a666a06e9acf534bbdf738896aea14d2"},{"exercise_id":"a1-u14-listen-e03","item_id":"en.gen.listen_choice.en-sixty","options_hash":"v1:3b46af28faa7bac34bd73296d66828ef397c9500716917ae754d795a7128c6cb"},{"exercise_id":"a1-u14-listen-e04","item_id":"en.gen.listen_choice.en-cent","options_hash":"v1:0ecd032025bc4b9cc45672fc9b5cbb24573008b91c00fba9b79f04b7d871dc71"},{"exercise_id":"a1-u14-listen-e05","item_id":"en.gen.listen_choice.en-fifty","options_hash":"v1:323808a67af98d684bdf4162d82b607aacc5fdea0a673f982167ea823b5f034a"},{"exercise_id":"a1-u14-listen-e06","item_id":"en.ex.9nc9yajdogxgts","options_hash":"v1:b30cecacb8baf31f965b6cf43aa08eec91b4b2bc58c8a88678a18c80ff63e405"},{"exercise_id":"a1-u14-listen-e07","item_id":"en.gen.listen_choice.en-thats-all","options_hash":"v1:d11c385117b380237142ab98e068a9f97fe2023096b7fbf7ae1dce36f3a205c4"},{"exercise_id":"a1-u14-listen-e08","item_id":"en.ex.49vbpba68dldfq","options_hash":"v1:38695a36affaa22cba3bd201eb8a77689189d0a4c46876100081c6507e693965"},{"exercise_id":"a1-u14-listen-e09","item_id":"en.gen.listen_choice.en-here-you-are","options_hash":"v1:620da772d1ab0ac6dd3d12cb207db41c5fb7a957d9d09a40adde28103dd12d79"},{"exercise_id":"a1-u14-listen-e10","item_id":"en.gen.listen_choice.en-dollar","options_hash":"v1:98432264465f48b092b2f081dc606a1b184401036c97cbe99a57d458d615396f"},{"exercise_id":"a1-u14-words-e03","item_id":"en.gen.translation_choice.en-id-like","options_hash":"v1:70b6bbca41057ebd50d80988e265f0c852159306cf12140b64c151032f208d33"},{"exercise_id":"a1-u14-words-e10","item_id":"en.gen.translation_choice.en-fifty","options_hash":"v1:25f66cc6e8b5aebc6f743fe69a4ce6a583d4f16ed5fb350a51b360cff4973944"},{"exercise_id":"a1-u14-final-e01","item_id":"en.gen.listen_choice.en-here-you-are","options_hash":"v1:8502d95724a07c4f857c481b69d46647f8a94484c0575877c192061bbfa50b5b"},{"exercise_id":"a1-u14-final-e05","item_id":"en.ex.jidnzetd0sdfs4","options_hash":"v1:1e0107dc1fa01d8685082efd246ef7a57617509f9656acc0d4e0e24de43249eb"},{"exercise_id":"a1-u14-final-e08","item_id":"en.gen.listen_choice.en-a-glass-of","options_hash":"v1:3660259b48c93b711b7a430412adb142946cad29b0baf82f4b013de5675ffa61"},{"exercise_id":"a1-u14-final-e10","item_id":"en.gen.translation_choice.en-forty","options_hash":"v1:8999d2e3feea79348a85d98828c0a13b91ad5c860bb2950dca9af5a5193d75f1"}]}}$content$::jsonb;
  v_bad text;
begin

-- Unidades planificadas: ya existen (fase C.2). Si faltan, se crean sin publicar.
insert into public.curriculum_units (id, language_code, level, position, title_es, title_en, description_es, emoji,
  objective_es, grammar, review_status, is_published)
select x.id, x.language_code, x.level, x.position, x.title_es, x.title_en, x.description_es, x.emoji,
  x.objective_es, x.grammar, x.review_status, false
from jsonb_to_recordset(d -> 'units')
  as x(id text, language_code text, level text, position smallint, title_es text, title_en text, description_es text,
       emoji text, objective_es text, grammar jsonb, review_status text)
on conflict (id) do nothing;

select string_agg(x.id, ', ') into v_bad
from jsonb_to_recordset(d -> 'units')
  as x(id text, language_code text, level text, position smallint, title_es text, title_en text, description_es text,
       emoji text, objective_es text, grammar jsonb, review_status text)
join public.curriculum_units u on u.id = x.id
where (u.language_code, u.level, u.position, u.title_es, u.title_en, u.description_es, u.emoji, u.objective_es,
       u.grammar, u.review_status)
   is distinct from (x.language_code, x.level, x.position, x.title_es, x.title_en, x.description_es, x.emoji,
       x.objective_es, x.grammar, x.review_status);
if v_bad is not null then
  raise exception 'planned_units: unidades ya cargadas con otros datos: %', v_bad;
end if;

insert into public.words (id, language_code, unit_id, text, translation_es, accepted_translations, ipa, romanization,
  emoji, example_en, example_es, difficulty, tags, is_published)
select x.id, x.language_code, x.unit_id, x.text, x.translation_es, x.accepted_translations, x.ipa, x.romanization,
  x.emoji, x.example_en, x.example_es, x.difficulty, x.tags, false
from jsonb_to_recordset(d -> 'words')
  as x(id text, language_code text, unit_id text, text text, translation_es text, accepted_translations text[],
       ipa text, romanization text, emoji text, example_en text, example_es text, difficulty smallint, tags text[])
on conflict (id) do nothing;

select string_agg(x.id, ', ') into v_bad
from jsonb_to_recordset(d -> 'words')
  as x(id text, language_code text, unit_id text, text text, translation_es text, accepted_translations text[],
       ipa text, romanization text, emoji text, example_en text, example_es text, difficulty smallint, tags text[])
join public.words w on w.id = x.id
where (w.language_code, w.unit_id, w.text, w.translation_es, w.accepted_translations, w.ipa, w.romanization, w.emoji,
       w.example_en, w.example_es, w.difficulty, w.tags)
   is distinct from (x.language_code, x.unit_id, x.text, x.translation_es, x.accepted_translations, x.ipa,
       x.romanization, x.emoji, x.example_en, x.example_es, x.difficulty, x.tags);
if v_bad is not null then
  raise exception 'planned_units: palabras ya cargadas con otros datos: %', v_bad;
end if;

insert into public.lessons (id, unit_id, position, title_es, objective_es, intro, takeaways, is_published)
select x.id, x.unit_id, x.position, x.title_es, x.objective_es, x.intro, x.takeaways, false
from jsonb_to_recordset(d -> 'lessons')
  as x(id text, unit_id text, position smallint, title_es text, objective_es text, intro jsonb, takeaways text[])
on conflict (id) do nothing;

select string_agg(x.id, ', ') into v_bad
from jsonb_to_recordset(d -> 'lessons')
  as x(id text, unit_id text, position smallint, title_es text, objective_es text, intro jsonb, takeaways text[])
join public.lessons l on l.id = x.id
where (l.unit_id, l.position, l.title_es, l.objective_es, l.intro, l.takeaways)
   is distinct from (x.unit_id, x.position, x.title_es, x.objective_es, x.intro, x.takeaways);
if v_bad is not null then
  raise exception 'planned_units: lecciones ya cargadas con otros datos: %', v_bad;
end if;

-- Catálogo de aprendizaje (content/catalog.ts): conceptos léxicos, ítems y conceptos de cada ítem.
declare
  v_bad text;
begin

-- Un concepto léxico por palabra: id = palabra, nivel = el de su unidad. Activo si la palabra está
-- publicada (como en el backfill de 20261107120000_learning_concepts.sql).
insert into public.concepts (id, language_code, kind, word_id, level, status)
select x.id, x.language_code, 'lexical', x.id, x.level,
       case when w.is_published then 'active' else 'draft' end
from jsonb_to_recordset(d -> 'catalog' -> 'concepts') as x(id text, language_code text, level text)
join public.words w on w.id = x.id
on conflict (id) do nothing;

update public.concepts c set status = 'active'
from jsonb_to_recordset(d -> 'catalog' -> 'concepts') as x(id text), public.words w
where c.id = x.id and w.id = x.id and w.is_published and c.status = 'draft';

select string_agg(id, ', ') into v_bad from (
  select x.id
  from jsonb_to_recordset(d -> 'catalog' -> 'concepts') as x(id text, language_code text, level text)
  left join public.concepts c on c.id = x.id
  where c.id is null
     or (c.language_code, c.kind, c.word_id, c.level) is distinct from (x.language_code, 'lexical', x.id, x.level)
  order by x.id limit 5
) z;
if v_bad is not null then
  raise exception 'catalog_concepts: conceptos ya cargados con otro idioma, tipo, palabra o nivel: %', v_bad;
end if;

insert into public.exercise_items (id, language_code, level, origin, type, assessment_mode, response_format,
  input_modality, response_privacy, status)
select x.id, x.language_code, x.level, x.origin, x.type, x.assessment_mode, x.response_format,
  x.input_modality, x.response_privacy, coalesce(x.status, 'active')
from jsonb_to_recordset(d -> 'catalog' -> 'items')
  as x(id text, language_code text, level text, origin text, type text, assessment_mode text,
       response_format text, input_modality text, response_privacy text, status text)
-- status: 'active' salvo que el documento diga otro (la fase C carga sus ítems en 'draft' para que
-- ningún repaso los tome antes de la revisión pedagógica; ver scripts/comprehension-sql.ts).
-- Sólo los que faltan: con V8, ON CONFLICT no alcanza (NOT NULL se valida antes que el conflicto).
where not exists (select 1 from public.exercise_items i where i.id = x.id)
on conflict (id) do nothing;

select string_agg(id, ', ') into v_bad from (
  select x.id
  from jsonb_to_recordset(d -> 'catalog' -> 'items')
    as x(id text, language_code text, level text, origin text, type text, assessment_mode text,
         response_format text, input_modality text, response_privacy text)
  join public.exercise_items i on i.id = x.id
  where (i.language_code, i.level, i.origin, i.type, i.assessment_mode, i.response_format,
         i.input_modality, i.response_privacy)
     is distinct from (x.language_code, x.level, x.origin, x.type, x.assessment_mode, x.response_format,
         x.input_modality, x.response_privacy)
  order by x.id limit 5
) z;
if v_bad is not null then
  raise exception 'catalog_items: ítems ya cargados con otra definición (un ítem no cambia: es un ítem nuevo): %', v_bad;
end if;

insert into public.item_concepts (item_id, concept_id, dimension, role, language_code)
select x.item_id, x.concept_id, x.dimension, x.role, x.language_code
from jsonb_to_recordset(d -> 'catalog' -> 'item_concepts')
  as x(item_id text, concept_id text, dimension text, role text, language_code text)
on conflict do nothing;

-- Los conceptos de un ítem ya cargado no cambian (§5): la base tiene que tener exactamente los del documento.
with doc as (
  select x.item_id, x.concept_id, x.dimension, x.role
  from jsonb_to_recordset(d -> 'catalog' -> 'item_concepts')
    as x(item_id text, concept_id text, dimension text, role text)
),
db as (
  select ic.item_id, ic.concept_id, ic.dimension, ic.role
  from public.item_concepts ic
  where ic.item_id in (select x ->> 'id' from jsonb_array_elements(d -> 'catalog' -> 'items') x)
),
diff as (
  (select * from db except select * from doc)
  union all
  (select * from doc except select * from db)
)
select string_agg(item_id, ', ') into v_bad from (
  select distinct item_id from diff order by item_id limit 5
) z;
if v_bad is not null then
  raise exception 'catalog_item_concepts: ítems ya cargados con otros conceptos (es un ítem nuevo): %', v_bad;
end if;

end;

-- Personas ficticias (content/personas.ts).
declare
  v_bad text;
begin

insert into public.content_personas (id, language_code, display_name, age, city, country, phone, email)
select x.id, x.language_code, x.display_name, x.age, x.city, x.country, x.phone, x.email
from jsonb_to_recordset(d -> 'catalog' -> 'personas')
  as x(id text, language_code text, display_name text, age smallint, city text, country text, phone text,
       email text)
on conflict (id) do nothing;

select string_agg(id, ', ') into v_bad from (
  select x.id
  from jsonb_to_recordset(d -> 'catalog' -> 'personas')
    as x(id text, language_code text, display_name text, age smallint, city text, country text, phone text,
         email text)
  join public.content_personas p on p.id = x.id
  where (p.language_code, p.display_name, p.age, p.city, p.country, p.phone, p.email)
     is distinct from (x.language_code, x.display_name, x.age, x.city, x.country, x.phone, x.email)
  order by x.id limit 5
) z;
if v_bad is not null then
  raise exception 'catalog_personas: personas ya cargadas con otros datos (una persona no cambia): %', v_bad;
end if;

end;

-- Objetivos de aprendizaje (content/objectives.ts) y sus relaciones.
declare
  v_bad text;
begin

select string_agg(id, ', ') into v_bad from (
  select x.id
  from jsonb_to_recordset(d -> 'catalog' -> 'objectives')
    as x(id text, language_code text, level text, cefr_activity text)
  join public.learning_objectives o on o.id = x.id
  where (o.language_code, o.level, o.cefr_activity) is distinct from (x.language_code, x.level, x.cefr_activity)
  order by x.id limit 5
) z;
if v_bad is not null then
  raise exception 'catalog_objectives: objetivos ya cargados con otro idioma, nivel o actividad (es un objetivo nuevo): %', v_bad;
end if;

insert into public.learning_objectives (id, language_code, level, cefr_activity, can_do_es, description_es,
  cefr_ref, group_key, position, status)
select x.id, x.language_code, x.level, x.cefr_activity, x.can_do_es, x.description_es, x.cefr_ref,
  x.group_key, x.position, x.status
from jsonb_to_recordset(d -> 'catalog' -> 'objectives')
  as x(id text, language_code text, level text, cefr_activity text, can_do_es text, description_es text,
       cefr_ref text, group_key text, position smallint, status text)
on conflict (id) do update set can_do_es = excluded.can_do_es, description_es = excluded.description_es,
  cefr_ref = excluded.cefr_ref, group_key = excluded.group_key, position = excluded.position,
  status = excluded.status
where (learning_objectives.can_do_es, learning_objectives.description_es, learning_objectives.cefr_ref,
       learning_objectives.group_key, learning_objectives.position, learning_objectives.status)
   is distinct from (excluded.can_do_es, excluded.description_es, excluded.cefr_ref, excluded.group_key,
       excluded.position, excluded.status);

insert into public.objective_concepts (objective_id, concept_id, role, language_code)
select x.objective_id, x.concept_id, x.role, x.language_code
from jsonb_to_recordset(d -> 'catalog' -> 'objective_concepts')
  as x(objective_id text, concept_id text, role text, language_code text)
on conflict (objective_id, concept_id) do update set role = excluded.role
where objective_concepts.role is distinct from excluded.role;

insert into public.lesson_objectives (lesson_id, objective_id, role)
select x.lesson_id, x.objective_id, x.role
from jsonb_to_recordset(d -> 'catalog' -> 'lesson_objectives') as x(lesson_id text, objective_id text, role text)
on conflict (lesson_id, objective_id) do update set role = excluded.role
where lesson_objectives.role is distinct from excluded.role;

insert into public.item_objectives (item_id, objective_id, language_code)
select x.item_id, x.objective_id, x.language_code
from jsonb_to_recordset(d -> 'catalog' -> 'item_objectives')
  as x(item_id text, objective_id text, language_code text)
on conflict do nothing;

-- Relaciones que la base tiene y el contenido ya no: no se borran acá.
with objectives as (
  select x ->> 'id' id from jsonb_array_elements(d -> 'catalog' -> 'objectives') x
),
gone as (
  select 'concepto ' || oc.objective_id || '/' || oc.concept_id what
  from public.objective_concepts oc
  where oc.objective_id in (select id from objectives)
    and not exists (select 1 from jsonb_to_recordset(d -> 'catalog' -> 'objective_concepts')
                      as x(objective_id text, concept_id text)
                    where x.objective_id = oc.objective_id and x.concept_id = oc.concept_id)
  union all
  select 'lección ' || lo.lesson_id || '/' || lo.objective_id
  from public.lesson_objectives lo
  where lo.lesson_id in (select jsonb_array_elements_text(d -> 'catalog' -> 'scope_lessons'))
    and not exists (select 1 from jsonb_to_recordset(d -> 'catalog' -> 'lesson_objectives')
                      as x(lesson_id text, objective_id text)
                    where x.lesson_id = lo.lesson_id and x.objective_id = lo.objective_id)
  union all
  select 'ítem ' || io.item_id || '/' || io.objective_id
  from public.item_objectives io
  where io.item_id in (select x ->> 'id' from jsonb_array_elements(d -> 'catalog' -> 'items') x)
    and not exists (select 1 from jsonb_to_recordset(d -> 'catalog' -> 'item_objectives')
                      as x(item_id text, objective_id text)
                    where x.item_id = io.item_id and x.objective_id = io.objective_id)
)
select string_agg(what, ', ') into v_bad from (select what from gone order by what limit 5) z;
if v_bad is not null then
  raise exception 'catalog_objectives: relaciones que el contenido ya no tiene (quitarlas requiere una migración escrita a mano): %', v_bad;
end if;

end;

-- Versiones de los ítems (content/versions.ts).
declare
  v_bad text;
begin

perform 1 from public.exercise_items i
where i.id in (select x ->> 'item_id' from jsonb_array_elements(d -> 'catalog' -> 'versions') x)
order by i.id
for update;

select string_agg(item_id || '@' || content_hash, ', ') into v_bad from (
  select x.item_id, x.content_hash
  from jsonb_to_recordset(d -> 'catalog' -> 'versions')
    as x(item_id text, content_hash text, prompt_es text, payload jsonb, answer text,
         accepted_answers text[], explanation_es text, difficulty smallint, recommended_seconds smallint,
         grading_spec jsonb, generator text, generator_version text)
  join public.exercise_item_versions v on v.item_id = x.item_id and v.content_hash = x.content_hash
  where (v.prompt_es, v.payload, v.answer, v.accepted_answers, v.explanation_es, v.difficulty,
         v.recommended_seconds, v.grading_spec)
     is distinct from (x.prompt_es, x.payload, x.answer, x.accepted_answers, x.explanation_es, x.difficulty,
         x.recommended_seconds, x.grading_spec)
  order by 1, 2 limit 5
) z;
if v_bad is not null then
  raise exception 'catalog_versions: versiones ya cargadas con el mismo hash y otro contenido: %', v_bad;
end if;

insert into public.exercise_item_versions (item_id, version, content_hash, prompt_es, payload, answer,
  accepted_answers, explanation_es, difficulty, recommended_seconds, grading_spec, generator, generator_version)
select n.item_id,
  coalesce((select max(v.version) from public.exercise_item_versions v where v.item_id = n.item_id), 0)
    + row_number() over (partition by n.item_id order by n.ord),
  n.content_hash, n.prompt_es, n.payload, n.answer, n.accepted_answers, n.explanation_es, n.difficulty,
  n.recommended_seconds, n.grading_spec, n.generator, n.generator_version
from (
  select distinct on (x.item_id, x.content_hash) x.*, t.ord
  from jsonb_array_elements(d -> 'catalog' -> 'versions') with ordinality as t(j, ord),
    jsonb_to_record(t.j)
      as x(item_id text, content_hash text, prompt_es text, payload jsonb, answer text,
           accepted_answers text[], explanation_es text, difficulty smallint, recommended_seconds smallint,
           grading_spec jsonb, generator text, generator_version text)
  where not exists (select 1 from public.exercise_item_versions v
                    where v.item_id = x.item_id and v.content_hash = x.content_hash)
  order by x.item_id, x.content_hash, t.ord
) n
order by n.item_id, n.ord;

update public.exercise_items i set current_version_id = v.id
from jsonb_to_recordset(d -> 'catalog' -> 'current_versions') as x(item_id text, content_hash text)
join public.exercise_item_versions v on v.item_id = x.item_id and v.content_hash = x.content_hash
where i.id = x.item_id and i.current_version_id is distinct from v.id;

end;

-- Conjuntos de opciones (content/option-sets.ts).
declare
  v_bad text;
begin

select string_agg(item_id || '@' || options_hash, ', ') into v_bad from (
  select x.item_id, x.options_hash
  from jsonb_to_recordset(d -> 'catalog' -> 'option_sets')
    as x(item_id text, version_hash text, options_hash text)
  left join public.exercise_item_versions v on v.item_id = x.item_id and v.content_hash = x.version_hash
  where v.id is null
  order by 1, 2 limit 5
) z;
if v_bad is not null then
  raise exception 'catalog_option_sets: conjuntos de una versión que no existe: %', v_bad;
end if;

select string_agg(item_id || '@' || options_hash, ', ') into v_bad from (
  select x.item_id, x.options_hash
  from jsonb_to_recordset(d -> 'catalog' -> 'option_sets')
    as x(item_id text, version_hash text, options_hash text, format text, options jsonb, answer_index smallint)
  join public.exercise_item_versions v on v.item_id = x.item_id and v.content_hash = x.version_hash
  join public.exercise_option_sets s on s.item_version_id = v.id and s.options_hash = x.options_hash
  where (s.format, s.options, s.answer_index) is distinct from (x.format, x.options, x.answer_index)
  order by 1, 2 limit 5
) z;
if v_bad is not null then
  raise exception 'catalog_option_sets: conjuntos ya cargados con el mismo hash y otras opciones: %', v_bad;
end if;

insert into public.exercise_option_sets (item_id, item_version_id, options_hash, format, options, answer_index,
  origin, generator, generator_version)
select x.item_id, v.id, x.options_hash, x.format, x.options, x.answer_index, x.origin, x.generator,
  x.generator_version
from jsonb_array_elements(d -> 'catalog' -> 'option_sets') with ordinality as t(j, ord),
  jsonb_to_record(t.j)
    as x(item_id text, version_hash text, options_hash text, format text, options jsonb, answer_index smallint,
         origin text, generator text, generator_version text)
join public.exercise_item_versions v on v.item_id = x.item_id and v.content_hash = x.version_hash
where not exists (select 1 from public.exercise_option_sets s
                  where s.item_version_id = v.id and s.options_hash = x.options_hash)
order by t.ord;

end;


insert into public.exercises (id, lesson_id, position, type, skill, prompt_es, payload, answer, accepted_answers,
  explanation_es, difficulty, recommended_seconds, is_published, item_id, item_version_id, option_set_id)
select x.id, x.lesson_id, x.position, x.type, x.skill, x.prompt_es, x.payload, x.answer, x.accepted_answers,
  x.explanation_es, x.difficulty, x.recommended_seconds, false, cp.item_id, cv.version_id, cs.id
from jsonb_to_recordset(d -> 'exercises')
  as x(id text, lesson_id text, position smallint, type text, skill text, prompt_es text, payload jsonb, answer text,
       accepted_answers text[], explanation_es text, difficulty smallint, recommended_seconds smallint)
left join (select y.exercise_id, y.item_id
           from jsonb_to_recordset(d -> 'catalog' -> 'placements') as y(exercise_id text, item_id text)) cp
  on cp.exercise_id = x.id
left join (select y.exercise_id, v.id as version_id
           from jsonb_to_recordset(d -> 'catalog' -> 'placement_versions')
             as y(exercise_id text, item_id text, content_hash text)
           join public.exercise_item_versions v on v.item_id = y.item_id and v.content_hash = y.content_hash) cv
  on cv.exercise_id = x.id and cp.item_id is not null
left join (select y.exercise_id, y.options_hash
           from jsonb_to_recordset(d -> 'catalog' -> 'placement_option_sets')
             as y(exercise_id text, item_id text, options_hash text)) co
  on co.exercise_id = x.id
left join public.exercise_option_sets cs on cs.item_version_id = cv.version_id and cs.options_hash = co.options_hash
on conflict (id) do nothing;

select string_agg(x.id, ', ') into v_bad
from jsonb_to_recordset(d -> 'exercises')
  as x(id text, lesson_id text, position smallint, type text, skill text, prompt_es text, payload jsonb, answer text,
       accepted_answers text[], explanation_es text, difficulty smallint, recommended_seconds smallint)
join public.exercises e on e.id = x.id
where (e.lesson_id, e.position, e.type, e.skill, e.prompt_es, e.payload, e.answer, e.accepted_answers,
       e.explanation_es, e.difficulty, e.recommended_seconds)
   is distinct from (x.lesson_id, x.position, x.type, x.skill, x.prompt_es, x.payload, x.answer, x.accepted_answers,
       x.explanation_es, x.difficulty, x.recommended_seconds);
if v_bad is not null then
  raise exception 'planned_units: ejercicios ya cargados con otro contenido: %', v_bad;
end if;

insert into public.exercise_words (exercise_id, word_id)
select x ->> 'id', w
from jsonb_array_elements(d -> 'exercises') x, jsonb_array_elements_text(x -> 'words') w
on conflict do nothing;

-- Ubicaciones (content/catalog.ts, Catalog.placements): exercises.item_id.
declare
  v_bad text;
begin

select string_agg(exercise_id, ', ') into v_bad from (
  select x.exercise_id
  from jsonb_to_recordset(d -> 'catalog' -> 'placements') as x(exercise_id text, item_id text)
  left join public.exercises e on e.id = x.exercise_id
  left join public.lessons l on l.id = e.lesson_id
  left join public.curriculum_units u on u.id = l.unit_id
  left join public.exercise_items i on i.id = x.item_id
  where e.id is null or i.id is null
     or u.language_code is distinct from i.language_code
     or e.type is distinct from i.type
  order by x.exercise_id limit 5
) z;
if v_bad is not null then
  raise exception 'catalog_placements: ejercicios sin fila, sin ítem o con un ítem de otro idioma o tipo: %', v_bad;
end if;

-- Si cambia de ítem, la versión pasa a la que el documento le asigna en el ítem nuevo (ya cargada), o
-- a nula si el documento no trae versiones. El conjunto lo corrige OPTION_SETS_PLACE_SQL (FK diferida).
update public.exercises e
set item_id = x.item_id,
    item_version_id = case when e.item_id = x.item_id then e.item_version_id else (
      select v.id
      from jsonb_to_recordset(d -> 'catalog' -> 'placement_versions')
        as pv(exercise_id text, item_id text, content_hash text)
      join public.exercise_item_versions v on v.item_id = pv.item_id and v.content_hash = pv.content_hash
      where pv.exercise_id = e.id and pv.item_id = x.item_id) end
from jsonb_to_recordset(d -> 'catalog' -> 'placements') as x(exercise_id text, item_id text)
where e.id = x.exercise_id and e.item_id is distinct from x.item_id;

end;

-- Versión de cada ubicación (content/versions.ts).
declare
  v_bad text;
begin

select string_agg(exercise_id, ', ') into v_bad from (
  select x.exercise_id
  from jsonb_to_recordset(d -> 'catalog' -> 'placement_versions')
    as x(exercise_id text, item_id text, content_hash text)
  left join public.exercises e on e.id = x.exercise_id
  left join public.exercise_item_versions v on v.item_id = x.item_id and v.content_hash = x.content_hash
  where e.id is null or v.id is null or e.item_id is distinct from x.item_id
  order by 1 limit 5
) z;
if v_bad is not null then
  raise exception 'catalog_versions: ubicaciones sin fila, sin versión o de otro ítem: %', v_bad;
end if;

update public.exercises e set item_version_id = v.id
from jsonb_to_recordset(d -> 'catalog' -> 'placement_versions')
  as x(exercise_id text, item_id text, content_hash text)
join public.exercise_item_versions v on v.item_id = x.item_id and v.content_hash = x.content_hash
where e.id = x.exercise_id and e.item_version_id is distinct from v.id;

-- Checksum de la duplicación transitoria (§5): exercises conserva la copia que lee la app.
select string_agg(id, ', ') into v_bad from (
  select e.id
  from public.exercises e
  join public.exercise_item_versions v on v.id = e.item_version_id
  where e.id in (select x ->> 'exercise_id' from jsonb_array_elements(d -> 'catalog' -> 'placement_versions') x)
    and (e.prompt_es, case when v.payload ? 'options' then e.payload else e.payload - 'options' end, e.answer,
         e.accepted_answers, e.explanation_es, e.difficulty, e.recommended_seconds)
     is distinct from (v.prompt_es, v.payload, v.answer, v.accepted_answers, v.explanation_es, v.difficulty,
         v.recommended_seconds)
  order by e.id limit 5
) z;
if v_bad is not null then
  raise exception 'catalog_versions: la copia de exercises no coincide con su versión: %', v_bad;
end if;

end;

-- Conjunto vigente de cada ubicación de elección (content/option-sets.ts).
declare
  v_bad text;
begin

select string_agg(exercise_id, ', ') into v_bad from (
  select x.exercise_id
  from jsonb_to_recordset(d -> 'catalog' -> 'placement_option_sets')
    as x(exercise_id text, item_id text, options_hash text)
  left join public.exercises e on e.id = x.exercise_id
  left join public.exercise_option_sets s
    on s.item_version_id = e.item_version_id and s.options_hash = x.options_hash
  where e.id is null or e.item_id is distinct from x.item_id or s.id is null
  order by 1 limit 5
) z;
if v_bad is not null then
  raise exception 'catalog_option_sets: ubicaciones sin fila, de otro ítem o sin ese conjunto en su versión: %', v_bad;
end if;

update public.exercises e set option_set_id = s.id
from jsonb_to_recordset(d -> 'catalog' -> 'placement_option_sets')
  as x(exercise_id text, item_id text, options_hash text)
join public.exercise_option_sets s on s.options_hash = x.options_hash
where e.id = x.exercise_id and s.item_version_id = e.item_version_id
  and e.option_set_id is distinct from s.id;

-- Checksum de la duplicación transitoria: exercises conserva la copia que lee la app.
select string_agg(id, ', ') into v_bad from (
  select e.id
  from public.exercises e
  join public.exercise_option_sets s on s.id = e.option_set_id
  where e.id in (select x ->> 'exercise_id' from jsonb_array_elements(d -> 'catalog' -> 'placement_option_sets') x)
    and ((select jsonb_agg(o -> 'text' order by n) from jsonb_array_elements(s.options) with ordinality as t(o, n))
           is distinct from e.payload -> 'options'
         or s.options -> s.answer_index::integer ->> 'text' is distinct from e.answer)
  order by e.id limit 5
) z;
if v_bad is not null then
  raise exception 'catalog_option_sets: la copia de exercises no coincide con su conjunto: %', v_bad;
end if;

select string_agg(id, ', ') into v_bad from (
  select e.id
  from jsonb_to_recordset(d -> 'catalog' -> 'placement_versions') as x(exercise_id text)
  join public.exercises e on e.id = x.exercise_id
  where e.type in ('image_choice', 'translation_choice', 'fill_blank', 'listen_choice', 'context_choice')
    and e.option_set_id is null
  order by e.id limit 5
) z;
if v_bad is not null then
  raise exception 'catalog_option_sets: ubicaciones de elección con versión y sin conjunto: %', v_bad;
end if;

end;

end
$polygo_content$;
